DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_DUALORDER' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_DUALORDER_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_TEXT_1','The Dual Order[NEWLINE]Faith-supported military infrastructure and defensive campaigning[NEWLINE]Domination; Culture/Diplomacy through a strong religious economy[NEWLINE][NEWLINE]Build the religious and military infrastructure that makes trained units durable, retain positive Faith income, and choose conflicts your army can actually manage. Extra wars increase a capped modifier but also create real military liabilities.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_TEXT_2','Establish food, defense and Faith before pursuing multiple commitments. Plan at least one city with both military-training and religious infrastructure so normally trained units receive Zeal.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_TEXT_3','Use Halls of Concordance to strengthen training cities. Pair ranged damage with Templar finishing attacks and protect any religious unit providing adjacency support. During Golden Ages, complete useful military production.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_TEXT_4','Hold supply lines and friendly-territory positions while converting production into a coherent army. Keep a realistic peace plan; nominal Balance Pressure is not worth losing cities or your Faith-producing economy.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_TEXT_5','- Paired infrastructure supports Faith and Production while enabling Zeal.[NEWLINE]- Trained veterans retain a useful territorial strength and kill-healing package.[NEWLINE]- Golden Ages and Halls create effective military preparation windows.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_TEXT_6','- The strongest setup requires investment in two infrastructure groups.[NEWLINE]- Balance Pressure needs positive Faith income and has a war-count cap.[NEWLINE]- Religious support units are vulnerable, and territorial conditions limit some bonuses.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_TEXT_7','- Threaten the Faith and training centres rather than trading endlessly into prepared positions.[NEWLINE]- Draw forces away from favourable territory and protect wounded units from Templar finishes.[NEWLINE]- Avoid creating extra fronts that benefit Severin without applying meaningful pressure.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_TEXT_8','- Declaring token wars only to raise the pressure indicator.[NEWLINE]- Training in a city missing one half of the Zeal requirement.[NEWLINE]- Treating a General as a substitute for the Templar''s specified religious adjacency.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Urgal: A prepared territorial defense with trained units and kill healing can help absorb the potion window; the attack bonus remains dangerous.[NEWLINE][NEWLINE]McPvP: Defended border cities and a functioning production base make flag runs and sustained infiltration more difficult.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Filthy Realm: Disruption of Faith-supporting cities, training and movement can break the intended combined-arms timing.[NEWLINE][NEWLINE]Beyond the Sky: Fast land forces can avoid the main fortified formation and threaten the support and approaches it cannot cover.');
