INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC_GUIDE_DUALORDER_LEADER_DESCRIPTION',Text FROM Language_en_US WHERE Tag='TXT_KEY_LEADER_GRANDMASTER_SEVERIN';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_BACKGROUND','Build the religious and military infrastructure that makes trained units durable, retain positive Faith income, and choose conflicts your army can actually manage. Extra wars increase a capped modifier but also create real military liabilities.');
