INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_LEADER_BACKGROUND','Build the religious and military infrastructure that makes trained units durable, retain positive Faith income, and choose conflicts your army can actually manage. Extra wars increase a capped modifier but also create real military liabilities.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC_GUIDE_DUALORDER_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_LEADER_GRANDMASTER_SEVERIN_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_STRATEGY','Build the religious and military infrastructure that makes trained units durable, retain positive Faith income, and choose conflicts your army can actually manage. Extra wars increase a capped modifier but also create real military liabilities.[NEWLINE][NEWLINE]Establish food, defense and Faith before pursuing multiple commitments. Plan at least one city with both military-training and religious infrastructure so normally trained units receive Zeal.[NEWLINE][NEWLINE]Use Halls of Concordance to strengthen training cities. Pair ranged damage with Templar finishing attacks and protect any religious unit providing adjacency support. During Golden Ages, complete useful military production.[NEWLINE][NEWLINE]Hold supply lines and friendly-territory positions while converting production into a coherent army. Keep a realistic peace plan; nominal Balance Pressure is not worth losing cities or your Faith-producing economy.');
