INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_DUALORDER_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Urgal: A prepared territorial defense with trained units and kill healing can help absorb the potion window; the attack bonus remains dangerous.[NEWLINE][NEWLINE]McPvP: Defended border cities and a functioning production base make flag runs and sustained infiltration more difficult.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Filthy Realm: Disruption of Faith-supporting cities, training and movement can break the intended combined-arms timing.[NEWLINE][NEWLINE]Beyond the Sky: Fast land forces can avoid the main fortified formation and threaten the support and approaches it cannot cover.');
